public void writeTo(Object obj, String type, OutputStream os) throws IOException {
  if (!(obj instanceof String))   throw new IOException("\"" + getDataFlavors()[0].getMimeType() + "\" DataContentHandler requires String object, "+ "was given object of type "+ obj.getClass().toString());
  String enc = null;
  OutputStreamWriter osw = null;
  try {
    enc = getCharset(type);
    osw = new OutputStreamWriter(new NoCloseOutputStream(os), enc);
  } catch (IllegalArgumentException | UnsupportedCharsetException | IllegalCharsetNameException iex) {
    osw = new OutputStreamWriter(new NoCloseOutputStream(os), "UTF-8");
  }
  String s = (String) obj;
  osw.write(s, 0, s.length());
  osw.close();
}
